    {
      "op": "replace",
      "path": "/workflow/nodes/evaluate/code",
      "value": "import json\nimport re\nimport datetime\ntry:\n    vars['route'] = 'identity'\n    vars['identity_speech'] = 'I could not complete that step. I cannot discuss account information until the required checks are complete.'\n    vars['human_speech'] = 'Please clarify whether you want a person to take over.'\n    vars['collection_speech'] = ''\n    vars['action_name'] = ''\n    vars['action_instruction'] = ''\n    vars['action_payload'] = dict()\n    vars['farewell_speech'] = 'Thank you. Goodbye.'\n    vars['close_outcome'] = ''\n    vars['close_reason'] = ''\n    def unpack(value, default):\n        if isinstance(value, str):\n            try:\n                value = json.loads(value)\n            except Exception:\n                return default\n        return value if isinstance(value, type(default)) else default\n    f = unpack(vars.get('flow'), dict())\n    initial = not bool(f)\n    defaults = dict(stage='name', phase='', name_asks=1, declines=0, talk_refusals=0, human_asked=False, human_wait=False, third=False, dob_ok=False, phone_ok=False, verified=False, loaded=False, wrong=0, buffer='', need_word_month=False, callback_invalid=0, callback_day='', callback_time='', products=[], queue=[], context_ids=[], readback_ids=[], offer=dict(), confirmed=False, hardship=False, support_wait=False, saved_slots=[], pending_speech='', transfer_reason='', notes=dict(), service_wait=False, finalizing=False, request_number=0, handled_number=0)\n    for key, value in defaults.items():\n        f.setdefault(key, value)\n    vars['flow'] = f\n    now = datetime.datetime.fromisoformat(str(vars.get('now', '')).replace('Z', '+00:00'))\n    today = now.date()\n    holidays = set(['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01'])\n    months = dict(january=1, february=2, march=3, april=4, may=5, june=6, july=7, august=8, september=9, october=10, november=11, december=12)\n    weekdays = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']\n    ones = dict(zero=0, oh=0, one=1, two=2, three=3, four=4, five=5, six=6, seven=7, eight=8, nine=9, ten=10, eleven=11, twelve=12, thirteen=13, fourteen=14, fifteen=15, sixteen=16, seventeen=17, eighteen=18, nineteen=19, twenty=20, thirty=30, forty=40, fifty=50, sixty=60, seventy=70, eighty=80, ninety=90)\n    ordinals = dict(first='one', second='two', third='three', fourth='four', fifth='five', sixth='six', seventh='seven', eighth='eight', ninth='nine', tenth='ten', eleventh='eleven', twelfth='twelve', thirteenth='thirteen', fourteenth='fourteen', fifteenth='fifteen', sixteenth='sixteen', seventeenth='seventeen', eighteenth='eighteen', nineteenth='nineteen', twentieth='twenty', thirtieth='thirty')\n    def business(day):\n        return day.weekday() < 5 and day.isoformat() not in holidays\n    def next_business(day):\n        day += datetime.timedelta(days=1)\n        while not business(day):\n            day += datetime.timedelta(days=1)\n        return day\n    def add_business(day, count):\n        for unused in range(count):\n            day = next_business(day)\n        return day\n    def last_business_week(day):\n        end = day - datetime.timedelta(days=day.weekday()) + datetime.timedelta(days=4)\n        while not business(end):\n            end -= datetime.timedelta(days=1)\n        return end\n    attempt_day = last_business_week(today)\n    if attempt_day == today:\n        attempt_day = last_business_week(today + datetime.timedelta(days=7))\n    def clean(text):\n        text = str(text or '').strip().lower()\n        text = re.sub(r'(?<=[a-z])-(?=[a-z])', ' ', text)\n        return re.sub(r'\\s+', ' ', text)\n    def number(text):\n        s = clean(text)\n        s = re.sub(r'\\b(?:each|exactly|please|total)\\b', '', s).strip()\n        if re.fullmatch(r'\\d{1,3}(?:,\\d{3})+(?:\\.\\d+)?', s):\n            s = s.replace(',', '')\n        if re.fullmatch(r'\\d+(?:\\.\\d+)?', s):\n            value = float(s)\n            return value if 0 <= value < 1000000000000000 else None\n        if re.search(r'[-+\\d,]', s):\n            return None\n        words = [ordinals.get(w, w) for w in s.split() if w != 'and']\n        if not words:\n            return None\n        if 'point' in words:\n            pos = words.index('point')\n            whole = number(' '.join(words[:pos]))\n            tail = words[pos + 1:]\n            if whole is None or whole != int(whole) or not tail or any(w not in ones or ones[w] > 9 for w in tail):\n                return None\n            return float(str(int(whole)) + '.' + ''.join(str(ones[w]) for w in tail))\n        total = 0\n        part = 0\n        previous = ''\n        for word in words:\n            if word in ones:\n                if previous in ones and not (ones[previous] >= 20 and ones[previous] % 10 == 0 and ones[word] < 10):\n                    return None\n                part += ones[word]\n            elif word == 'hundred':\n                if not 1 <= part <= 9:\n                    return None\n                part *= 100\n            elif word in ['thousand', 'million']:\n                if part <= 0:\n                    return None\n                total += part * (1000 if word == 'thousand' else 1000000)\n                part = 0\n            else:\n                return None\n            previous = word\n        return float(total + part)\n    def money(value):\n        return format(float(value), '.15g')\n    def spoken_date(day):\n        return str(day.day) + ' ' + list(months.keys())[day.month - 1].capitalize() + ' ' + str(day.year)\n    def year_number(text):\n        s = clean(text)\n        if re.fullmatch(r'\\d{4}', s):\n            return int(s)\n        value = number(s)\n        if value is not None and value == int(value) and 1000 <= value <= 9999:\n            return int(value)\n        words = s.split()\n        for split in range(1, len(words)):\n            first = number(' '.join(words[:split]))\n            last = number(' '.join(words[split:]))\n            if first is not None and last is not None and 10 <= first <= 29 and 0 <= last <= 99:\n                return int(first) * 100 + int(last)\n        return None\n    def parse_date(text, context='', birth=False):\n        raw = str(text or '').strip().lower()\n        if not raw:\n            return ('missing', None, context)\n        match = re.fullmatch(r'(\\d{4})-(\\d{2})-(\\d{2})', raw)\n        if match:\n            try:\n                day = datetime.date(*[int(x) for x in match.groups()])\n                return ('exact', day, day.strftime('%Y-%m'))\n            except Exception:\n                return ('invalid', None, context)\n        s = clean(raw)\n        match = re.fullmatch(r'(\\d{1,2})[ /.-]+(\\d{1,2})[ /.-]+(\\d{4})', s)\n        if match:\n            a, b, c = [int(x) for x in match.groups()]\n            try:\n                day = datetime.date(c, b, a)\n                return ('exact', day, day.strftime('%Y-%m'))\n            except Exception:\n                return ('invalid', None, context)\n        s = re.sub(r'(\\d)(?:st|nd|rd|th)\\b', r'\\1', s)\n        s = re.sub(r'\\b(?:on|the|of|at)\\b', ' ', s)\n        s = re.sub(r'\\s+', ' ', s).strip()\n        weekday = next((w for w in weekdays if re.search(r'\\b' + w + r'\\b', s)), '')\n        month_name = next((m for m in months if re.search(r'\\b' + m + r'\\b', s)), '')\n        if not birth:\n            relative_days = dict(today=0, tomorrow=1)\n            if s in relative_days or s in ['day after tomorrow', 'day after next']:\n                return ('exact', today + datetime.timedelta(days=relative_days.get(s, 2)), context)\n            relative = re.fullmatch(r'in (.+?) (days?|weeks?)', s)\n            if relative:\n                count = number(relative.group(1))\n                if count is not None and count == int(count):\n                    return ('exact', today + datetime.timedelta(days=int(count) * (7 if relative.group(2).startswith('week') else 1)), context)\n            if weekday and re.search(r'\\b(?:this|next)\\b', s) and not month_name:\n                base = today - datetime.timedelta(days=today.weekday())\n                if re.search(r'\\bnext\\b', s):\n                    base += datetime.timedelta(days=7)\n                day = base + datetime.timedelta(days=weekdays.index(weekday))\n                remainder = re.sub(r'\\b(?:this|next|' + weekday + r')\\b', '', s).strip()\n                if remainder:\n                    dom = number(remainder)\n                    if dom is None or dom != day.day:\n                        return ('ambiguous', None, context)\n                return ('exact', day, 'week:' + base.isoformat())\n        if month_name:\n            stripped = s\n            for w in weekdays:\n                stripped = re.sub(r'\\b' + w + r'\\b', '', stripped)\n            left, right = [part.strip() for part in stripped.split(month_name, 1)]\n            year = None\n            dom = None\n            explicit = re.search(r'\\b\\d{4}\\b', stripped)\n            if explicit:\n                year = int(explicit.group())\n                dom = number((left + ' ' + right).replace(explicit.group(), '').strip())\n            elif left:\n                dom = number(left)\n                year = year_number(right) if right else None\n            else:\n                words = right.split()\n                for split in range(1, len(words)):\n                    candidate_day = number(' '.join(words[:split]))\n                    candidate_year = year_number(' '.join(words[split:]))\n                    if candidate_day is not None and candidate_day == int(candidate_day) and 1 <= candidate_day <= 31 and candidate_year:\n                        dom, year = candidate_day, candidate_year\n                        break\n                if dom is None:\n                    dom = number(right)\n            if year is None and not birth:\n                if context and not context.startswith('week:'):\n                    parts = context.split('-')\n                    if len(parts) == 2 and int(parts[1]) == months[month_name]:\n                        year = int(parts[0])\n                if year is None and months[month_name] == today.month:\n                    year = today.year\n            if year is not None:\n                context = str(year).zfill(4) + '-' + str(months[month_name]).zfill(2)\n            if year is not None and dom is not None and dom == int(dom):\n                try:\n                    day = datetime.date(year, months[month_name], int(dom))\n                    if weekday and weekdays[day.weekday()] != weekday:\n                        return ('ambiguous', None, context)\n                    return ('exact', day, context)\n                except Exception:\n                    return ('invalid', None, context)\n            if birth:\n                return ('incomplete', None, context)\n        if not birth and context:\n            remainder = s\n            if weekday:\n                remainder = re.sub(r'\\b' + weekday + r'\\b', '', remainder).strip()\n            dom = number(remainder) if remainder else None\n            try:\n                if context.startswith('week:'):\n                    base = datetime.date.fromisoformat(context[5:])\n                    matches = [base + datetime.timedelta(days=i) for i in range(7) if (dom is None and not remainder or dom == (base + datetime.timedelta(days=i)).day) and (not weekday or i == weekdays.index(weekday))]\n                    if len(matches) == 1:\n                        return ('exact', matches[0], context)\n                elif dom is not None and dom == int(dom) and 1 <= dom <= 31:\n                    year, month = [int(x) for x in context.split('-')]\n                    day = datetime.date(year, month, int(dom))\n                    if not weekday or weekdays[day.weekday()] == weekday:\n                        return ('exact', day, context)\n                    return ('ambiguous', None, context)\n            except Exception:\n                return ('invalid', None, context)\n        if not birth:\n            vague = bool(re.search(r'week|month|salary|pay\\s*day|paycheck|pay cheque|wages|paid|sometime|some time|soon|later|end|middle|beginning|start|eventually', s))\n            if vague and not re.search(r'\\b\\d{1,2}\\b', s):\n                if re.search(r'next month|month after', s):\n                    future = (today.replace(day=1) + datetime.timedelta(days=32)).replace(day=1)\n                    context = future.strftime('%Y-%m')\n                elif re.search(r'next week|week after|following week', s):\n                    context = 'week:' + (today - datetime.timedelta(days=today.weekday()) + datetime.timedelta(days=7)).isoformat()\n                elif 'week' in s and 'this' in s:\n                    context = 'week:' + (today - datetime.timedelta(days=today.weekday())).isoformat()\n                elif 'month' in s and not month_name:\n                    context = today.strftime('%Y-%m')\n                return ('vague', None, context)\n            if weekday:\n                return ('ambiguous', None, context)\n        return ('incomplete', None, context)\n    def item(pid):\n        return next(p for p in f['products'] if p['product_id'] == pid)\n    def take_prefix(text):\n        text = f['pending_speech'] + text\n        f['pending_speech'] = ''\n        return text\n    def ask_id(text):\n        vars['identity_speech'] = take_prefix(text)\n        f['last_id_question'] = text\n        vars['route'] = 'callback_question' if f['third'] else 'name_question' if f['stage'] == 'name' else 'identity'\n    def ask_human(text):\n        vars['human_speech'] = take_prefix(text)\n        vars['route'] = 'human_question'\n    def ask_pay(text, phase=''):\n        if not f['verified'] or not f['loaded'] or not f['products']:\n            ask_id('I cannot discuss account information until the required checks are complete.')\n            return\n        if phase:\n            f['phase'] = phase\n        vars['collection_speech'] = take_prefix(text)\n        f['last_question'] = text\n        vars['route'] = 'collection'\n    def finish(outcome, reason='', prefix=''):\n        f['close_candidate'] = dict(outcome=outcome, reason=reason)\n        vars['close_outcome'] = outcome\n        vars['close_reason'] = reason\n        vars['farewell_speech'] = take_prefix(prefix + 'Thank you. Goodbye.')\n        vars['route'] = 'finish'\n    def action(name, payload):\n        if name in ['create_promise', 'add_note'] and (not f['verified'] or not f['loaded']):\n            ask_id('I cannot complete an account request until the required checks are complete.')\n            return\n        if name == 'transfer_to_agent':\n            if f['notes']:\n                finalize()\n                return\n            f['finalizing'] = False\n            f['confirmed'] = False\n            f['queue'] = []\n        f['request_number'] += 1\n        f['action'] = dict(name=name, payload=payload, number=f['request_number'])\n        f['service_wait'] = False\n        vars['action_name'] = name\n        vars['action_payload'] = payload\n        prefix = take_prefix('')\n        vars['action_instruction'] = 'First say exactly this text if nonempty: ' + prefix + '\\nThen immediately CALL ' + name + ' once with these authorized values: ' + json.dumps(payload) + '. Do not ask another question, change the terms, call another bank tool or claim success before its result. After the result immediately follow the next authorized instruction.'\n        vars['route'] = 'actions'\n    def wait_service(name, payload, status):\n        f['service_wait'] = True\n        f['retry_action'] = dict(name=name, payload=payload, permitted=(str(status) == '500'))\n        vars['action_instruction'] = 'Say: I could not complete that request. Do not claim success or close the call. Wait for the caller. An explicit retry request permits repeating this operation only after the documented HTTP 500 failure. A request for a human must still receive the required help-first question or an authorized general transfer after insistence.'\n        vars['route'] = 'actions'\n    def labels(ids):\n        return ', '.join(item(pid)['label'] for pid in ids)\n    def resolve(reference, default_ids):\n        text = re.sub(r'^(?:the|my)\\s+', '', clean(reference))\n        if not text or text in ['current', 'this one', 'that one', 'it']:\n            return list(default_ids)\n        scope = f['readback_ids'] if f.get('correction_scope') else [p['product_id'] for p in f['products']]\n        if text in ['all', 'everything', 'all of them', 'all products', 'each product', 'all these', 'all promises']:\n            return list(scope)\n        if text in ['both', 'both of them']:\n            return list(scope) if len(scope) == 2 else []\n        if text in ['both loans', 'loans']:\n            return [p['product_id'] for p in f['products'] if p['type'] != 'credit_card' and p['product_id'] in scope]\n        exact = [p['product_id'] for p in f['products'] if text in [clean(p['label']), clean(p['product_id'])]]\n        if len(exact) == 1:\n            return exact\n        digits = re.findall(r'\\b\\d{4}\\b', text)\n        if len(digits) == 1:\n            exact = [p['product_id'] for p in f['products'] if p['type'] == 'credit_card' and str(p.get('card_last4', '')) == digits[0]]\n            return exact if len(exact) == 1 else []\n        if re.search(r'\\s+(?:and|&)\\s+', text):\n            found = []\n            for part in re.split(r'\\s+(?:and|&)\\s+', text):\n                ids = resolve(part, [])\n                if not ids:\n                    return []\n                found += ids\n            return [p['product_id'] for p in f['products'] if p['product_id'] in found]\n        aliases = dict(credit_card=['card', 'credit card'], personal_loan=['personal loan', 'personal', 