(p['label'] for p in f['products']) + '?', 'target', [])\n            return\n        statement['ids'] = list(ids)\n        f['context_ids'] = list(ids)\n        kind = statement.get('kind', 'unknown')\n        amount_text = str(statement.get('amount', '')).strip()\n        day_words = str(statement.get('day', '')).strip()\n        if kind not in ['proposal', 'paid', 'dispute', 'refuse', 'too_much'] or kind in ['paid', 'dispute', 'refuse'] and (amount_text or day_words):\n            clarify('Please clarify what you would like to do for ' + labels(ids) + '.', 'kind', ids)\n            return\n        if kind == 'proposal' and not amount_text and not day_words and not statement.get('valid_terms'):\n            clarify('Please repeat the product and the payment terms you proposed.', 'terms', ids)\n            return\n        recorded = [pid for pid in ids if item(pid)['status'] == 'recorded']\n        if recorded:\n            f['pending_speech'] += 'A recorded promise cannot be changed or cancelled during this call. You can change it in the mobile app. '\n            ids = [pid for pid in ids if pid not in recorded]\n            statement['ids'] = ids\n            if not ids:\n                f['queue'].pop(0)\n                advance()\n                return\n        if kind in ['paid', 'dispute']:\n            for pid in ids:\n                item(pid)['status'] = kind\n            if kind == 'paid':\n                f['pending_speech'] += 'Payments can take one business day to appear. '\n            f['queue'].pop(0)\n            advance()\n            return\n        if kind == 'refuse':\n            f['queue'].pop(0)\n            reject(ids)\n            return\n        if kind == 'too_much':\n            for pid in ids:\n                item(pid)['too_much'] = True\n            if not amount_text and not day_words and f.get('initial_today_context'):\n                f['queue'].pop(0)\n                f['initial_today_context'] = False\n                advance(