       elif amount > p['full']:\n                clarify('The proposed amount exceeds the past-due amount for your ' + p['label'] + '. Please clarify the payment terms you intend.', 'terms', ids)\n                return\n            selected_day = day\n            if date_kind == 'missing':\n                old_date = p.get('date', '') or old_entry.get('date', '')\n                if old_date:\n                    selected_day = datetime.date.fromisoformat(old_date)\n                elif f.get('initial_today_context'):\n                    selected_day = today\n                else:\n                    clarify('What exact day would you make that payment for ' + labels(ids) + '?', 'day', ids)\n                    return\n            elif date_kind == 'vague':\n                if not statement.get('vague_asked') and not any(item(selected)['vague_asks'] for selected in ids):\n                    statement['vague_asked'] = True\n                    for selected in ids:\n                        item(selected)['vague_asks'] = 1\n                        item(selected)['date_context'] = context\n                    clarify('What exact day do you mean?', 'day', ids)\n                    return\n                selected_day = datetime.date.fromisoformat(p['deadline'])\n                offer_kind = 'deadline'\n            elif date_kind != 'exact':\n                clarify('Please give the exact day, month and year you mean.', 'day', ids)\n                return\n            deadline = datetime.date.fromisoformat(p['deadline'])\n            if selected_day < today:\n                clarify('That date is in the past. What exact business day, from today through ' + spoken_date(deadline) + ', do you mean?', 'day', ids)\n                return\n            if selected_day > deadline:\n                selected_day = deadline\n                if not common_date:\n                    offer_kind = 'deadline'\n            elif not business(selected_day):\n                selected_day 